if ('scrollRestoration' in history) history.scrollRestoration = 'manual';

const resetInitialViewport = () => {
  const initialRoute = location.hash.replace(/^#/, '').split(/[/?]/)[0];
  if (initialRoute && initialRoute !== 'home' && initialRoute !== 'class') return;

  window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  requestAnimationFrame(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
  });
};

resetInitialViewport();
window.addEventListener('load', resetInitialViewport, { once: true });
window.addEventListener('pageshow', resetInitialViewport, { once: true });

(() => {
  const landing = document.querySelector('.landing');
  const siteHeader = document.querySelector('wine-site-header');
  const worksFlow = document.querySelector('.works-flow');
  const worksPage = document.querySelector('.works-page');
  const worksTiles = document.querySelector('.works-tiles');
  const worksGalleryPage = document.querySelector('.works-gallery-page');
  const worksModeTabs = document.querySelector('.works-mode-tabs');
  const worksModeLinks = [...document.querySelectorAll('.works-mode-tabs__tab')];
  const worksUxPage = document.querySelector('.works-ux-page');
  const worksUxSmile = document.querySelector('.works-ux-smile');
  const classPage = document.querySelector('.class-page');
  const classCapabilityPanel = document.querySelector('.class-panel--sticker');
  const classRingImages = [...document.querySelectorAll('.class-ring-card img')];
  const classRingMore = document.querySelector('.class-ring-more');
  const classRingStage = document.querySelector('.class-ring-stage');
  const classFeedbackCards = [...document.querySelectorAll('.class-feedback-hover')];
  const classStats = document.querySelector('.class-stats');
  const classCounters = [...document.querySelectorAll('.class-count[data-count]')];
  const classCanStage = document.querySelector('.class-can-stage');
  const classCanStory = document.querySelector('.class-can-story');
  const classCanLayerPanel = document.querySelector('.class-panel--can');
  const classSmileSticker = document.querySelector('.class-smile-sticker');
  const classStarSticker = document.querySelector('.class-star-sticker');
  /* Embedded, origin-clean sticker textures keep the WebGL peel available
     when this static site is opened directly with file://. Chromium assigns
     local image files opaque origins, so drawing those files into a canvas can
     otherwise taint the texture in an external browser. */
  const classSmileStickerTexture = 'data:image/jpeg;base64,';
  const classStarStickerTexture = 'data:image/jpeg;base64,';
  const classPortfolioReveal = document.querySelector('.class-portfolio-reveal');
  const classCurriculumCopyMask = document.querySelector('.class-curriculum-copy-mask');
  const classValueListMasks = [...document.querySelectorAll('.class-value-list-mask')];
  const classLessons = document.querySelector('.class-lessons');
  const classLessonRail = document.querySelector('.class-lessons__rail');
  const classLessonButtons = [...document.querySelectorAll('.class-lesson[data-lesson]')];
  const classLessonIndex = document.querySelector('.class-lessons__index');
  const classLessonTitle = document.querySelector('.class-lessons__content h2');
  const classLessonBody = document.querySelector('.class-lessons__content p');
  const classVariableTitles = [...document.querySelectorAll('.class-variable-title:not(.class-variable-title--warp)')];
  const classWarpTitles = [...document.querySelectorAll('.class-variable-title--warp')];
  const classPanels = [...document.querySelectorAll('.class-panel')];
  const homePage = document.querySelector('.hero-home');
  const uxTypeSwitcher = document.querySelector('.ux-type-switcher');
  const uxTypeButtons = [...document.querySelectorAll('.ux-type')];
  const uxProjectStage = document.querySelector('.ux-project-stage');
  const uxProjectPreview = document.querySelector('.ux-project-preview');
  const uxProjectDetail = document.querySelector('.ux-project-detail');
  const uxProjectDetailImage = document.querySelector('.ux-project-detail__image');
  const uiPhoneGallery = document.querySelector('.ui-phone-gallery');
  const uiPhoneTrack = document.querySelector('.ui-phone-track');
  const uiPhoneSequence = document.querySelector('.ui-phone-sequence');
  const uiPhoneCards = [...document.querySelectorAll('.ui-phone-card')];
  const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
  let wineScrollFrame = 0;
  let classCounterTimer = 0;
  let classCounterFrame = 0;
  let activeClassLesson = -1;
  let activeUxType = null;
  let uxDetailLoadToken = 0;

  const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

  const classLessonData = Array.from({ length: 16 }, (_, index) => ({
    title: index === 0
      ? '从功能到界面：界面初识与原型设计*'
      : `第 ${String(index + 1).padStart(2, '0')} 节课程内容`,
    body: '课程内容待补充'
  }));

  const prepareClassCounters = () => {
    if (!classStats || !classCounters.length) return;

    classCounters.forEach((counter, counterIndex) => {
      const target = counter.dataset.count ?? '';
      const accessibleTarget = document.createElement('span');
      accessibleTarget.className = 'sr-only';
      accessibleTarget.textContent = target;
      counter.textContent = '';
      counter.append(accessibleTarget);

      [...target].forEach((character, digitIndex) => {
        const targetDigit = Number(character);
        if (!Number.isInteger(targetDigit)) return;

        const reel = document.createElement('span');
        const track = document.createElement('span');
        const loops = 2 + ((counterIndex + digitIndex) % 2);
        const steps = loops * 10 + targetDigit;
        reel.className = 'class-count__digit';
        reel.setAttribute('aria-hidden', 'true');
        track.className = 'class-count__track';
        track.style.setProperty('--count-steps', String(steps));
        track.style.setProperty('--count-duration', `${1050 + counterIndex * 120 + digitIndex * 110}ms`);
        track.style.setProperty('--count-delay', `${counterIndex * 85 + digitIndex * 70}ms`);

        for (let step = 0; step <= steps; step += 1) {
          const number = document.createElement('span');
          number.textContent = String(step % 10);
          track.append(number);
        }

        reel.append(track);
        counter.append(reel);
      });
    });

  };

  prepareClassCounters();

  const finishClassCounters = () => {
    if (!classStats) return;
    classStats.classList.remove('is-counting');
    classStats.classList.add('is-count-complete');
  };

  const resetClassCounters = () => {
    window.clearTimeout(classCounterTimer);
    cancelAnimationFrame(classCounterFrame);
    classCounterTimer = 0;
    classCounterFrame = 0;
    classStats?.classList.remove('is-counting', 'is-count-complete');
  };

  const replayClassCounters = () => {
    if (!classStats) return;
    resetClassCounters();

    if (reduceMotion.matches) {
      finishClassCounters();
      return;
    }

    /* Start from the first reel cell on every Class route entry. Reading the
       layout between class removal and the next frame makes the transition
       restart both after a hard refresh and after an in-page route switch. */
    classStats.getBoundingClientRect();
    classCounterFrame = requestAnimationFrame(() => {
      classStats.classList.add('is-counting');
      classCounterTimer = window.setTimeout(finishClassCounters, 2100);
    });
  };

  const updateWorksWine = () => {
    if (!worksPage || landing.dataset.page !== 'works') return;

    const viewportHeight = Math.max(window.innerHeight, 1);
    const sectionTop = worksPage.getBoundingClientRect().top;
    const rawProgress = (-sectionTop - viewportHeight * 0.06) / (viewportHeight * 0.66);
    const progress = reduceMotion.matches ? clamp(rawProgress, 0, 1) : clamp(rawProgress, 0, 1);
    const eased = progress * progress * (3 - 2 * progress);
    const fragmentPhase = Math.min(progress * 1.25, 1);
    const fragmentOpacity = reduceMotion.matches ? 0 : Math.sin(Math.PI * fragmentPhase) * 0.84;

    worksPage.style.setProperty('--works-wine-whole-opacity', String(clamp(1 - progress * 2.25, 0, 1)));
    worksPage.style.setProperty('--works-wine-whole-scale', String(1 - eased * 0.035));
    worksPage.style.setProperty('--works-wine-whole-blur', `${(progress * 1.6).toFixed(2)}px`);
    worksPage.style.setProperty('--works-wine-fragment-opacity', String(fragmentOpacity));
    worksPage.style.setProperty('--works-wine-fragment-blur', `${(eased * 5.5).toFixed(2)}px`);
    worksPage.style.setProperty('--works-wine-fragment-scale', String(Math.max(0.18, 1 - eased * 0.82)));
    worksPage.style.setProperty('--works-wine-fragment-y', `${(eased * 45).toFixed(2)}vh`);
    worksPage.style.setProperty('--works-wine-left-x', `${(-eased * 35).toFixed(2)}cqw`);
    worksPage.style.setProperty('--works-wine-right-x', `${(eased * 35).toFixed(2)}cqw`);
    worksPage.style.setProperty('--works-wine-left-rotate', `${(-eased * 4).toFixed(2)}deg`);
    worksPage.style.setProperty('--works-wine-right-rotate', `${(eased * 4).toFixed(2)}deg`);
  };

  const replayWorksTileDrop = () => {
    if (!worksTiles) return;
    worksTiles.classList.remove('is-dropping');
    if (reduceMotion.matches) return;

    /* Reflow is intentional here: it lets the authored entrance replay after
       returning to the Works route without changing the tiles' resting layout. */
    worksTiles.getBoundingClientRect();
    worksTiles.classList.add('is-dropping');
  };

  const setWorksMode = (mode) => {
    if (!worksModeTabs) return;
    const activeMode = mode === 'ux' ? 'ux' : 'ui';
    if (worksModeTabs.dataset.activeMode !== activeMode) {
      worksModeTabs.dataset.activeMode = activeMode;
    }
    worksModeLinks.forEach((link) => {
      const selected = link.classList.contains(`works-mode-tabs__tab--${activeMode}`);
      if (selected) link.setAttribute('aria-current', 'page');
      else link.removeAttribute('aria-current');
    });
  };

  const updateWorksModeTabs = () => {
    if (!worksModeTabs || !worksUxPage || landing.dataset.page !== 'works') return;
    const viewportHeight = Math.max(window.innerHeight, 1);
    const uxSectionTop = worksUxPage.getBoundingClientRect().top;
    setWorksMode(uxSectionTop <= viewportHeight * 0.92 ? 'ux' : 'ui');
  };

  const updateWorksUxSmile = () => {
    if (!worksUxPage || !worksUxSmile || landing.dataset.page !== 'works') return;

    const viewportHeight = Math.max(window.innerHeight, 1);
    const sectionTop = worksUxPage.getBoundingClientRect().top;
    const stickyTravel = Math.max(worksUxPage.offsetHeight - viewportHeight, 0);
    const headerSafeShift = clamp(-sectionTop, 0, stickyTravel);
    const rawProgress = (viewportHeight - sectionTop) / (viewportHeight * 0.92);
    const progress = clamp(rawProgress, 0, 1);
    const eased = reduceMotion.matches ? (progress > 0 ? 1 : 0) : progress * progress * (3 - 2 * progress);
    const remaining = 1 - eased;
    const revealProgress = clamp((progress - 0.08) / 0.22, 0, 1);
    const revealOpacity = revealProgress * revealProgress * (3 - 2 * revealProgress);
    const foregroundProgress = clamp((eased - 0.94) / 0.06, 0, 1);
    const foregroundOpacity = foregroundProgress * foregroundProgress * (3 - 2 * foregroundProgress);

    /* Roll the complete disc in from the upper-right with a clearly readable
       arc. The approved settled scale and final CSS position remain unchanged. */
    worksUxPage.style.setProperty('--ux-smile-x', `${(remaining * 18).toFixed(2)}cqw`);
    worksUxPage.style.setProperty('--ux-smile-y', `${(-remaining * 14).toFixed(2)}cqw`);
    worksUxPage.style.setProperty('--ux-smile-rotate', `${(remaining * 120).toFixed(2)}deg`);
    worksUxPage.style.setProperty('--ux-smile-scale', String(1.05 + eased * 0.15));
    worksUxPage.style.setProperty('--ux-smile-opacity', String(revealOpacity));
    worksUxPage.style.setProperty('--ux-smile-blur', `${(remaining * 1.2).toFixed(2)}px`);
    worksUxPage.style.setProperty('--ux-smile-foreground-opacity', String(foregroundOpacity));
    /* Keep the interactive project tabs and star in their approved positions
       below the fixed public header while the taller UX board scrolls. */
    worksUxPage.style.setProperty('--ux-header-safe-shift', `${headerSafeShift.toFixed(2)}px`);
    worksUxPage.style.setProperty('--ux-board-opacity', '1');
    worksUxPage.style.setProperty('--ux-board-blur', '0px');
    worksUxPage.style.setProperty('--ux-board-x', '0');
  };

  const selectClassLesson = (nextIndex, { syncScroll = false, focus = false, centerRail = true } = {}) => {
    if (!classLessons || !classLessonButtons.length) return;
    const index = clamp(Number(nextIndex) || 0, 0, classLessonButtons.length - 1);
    activeClassLesson = index;

    classLessonButtons.forEach((button, buttonIndex) => {
      const selected = buttonIndex === index;
      button.classList.toggle('is-active', selected);
      button.setAttribute('aria-selected', String(selected));
      button.tabIndex = selected ? 0 : -1;
    });

    const lesson = classLessonData[index];
    if (classLessonIndex) classLessonIndex.textContent = `CLASS – ${String(index + 1).padStart(2, '0')}:`;
    if (classLessonTitle) classLessonTitle.textContent = lesson.title;
    if (classLessonBody) classLessonBody.textContent = lesson.body;
    const activeButton = classLessonButtons[index];
    if (centerRail) {
      classLessonRail?.scrollTo({
        top: activeButton.offsetTop - (classLessonRail.clientHeight - activeButton.offsetHeight) / 2,
        behavior: reduceMotion.matches ? 'auto' : 'smooth'
      });
    }
    if (focus) activeButton.focus({ preventScroll: true });

    if (syncScroll) {
      const sectionTop = window.scrollY + classLessons.getBoundingClientRect().top;
      const scrollable = Math.max(classLessons.offsetHeight - window.innerHeight, 1);
      const targetProgress = (index + .25) / classLessonButtons.length;
      window.scrollTo({
        top: Math.round(sectionTop + scrollable * targetProgress),
        behavior: reduceMotion.matches ? 'auto' : 'smooth'
      });
    }
  };

  const updateClassLessons = () => {
    if (!classLessons || landing.dataset.page !== 'class') return;
    const rect = classLessons.getBoundingClientRect();
    const scrollable = Math.max(classLessons.offsetHeight - window.innerHeight, 1);
    const progress = clamp(-rect.top / scrollable, 0, 1);
    const index = Math.min(classLessonButtons.length - 1, Math.floor(progress * classLessonButtons.length));
    if (index !== activeClassLesson) selectClassLesson(index);
  };

  const syncClassLessonRailAngle = () => {
    if (!classLessonRail) return;
    const diagonalShift = classLessonRail.scrollTop * Math.tan(9.4 * Math.PI / 180);
    classLessonRail.style.setProperty('--lesson-rail-shift-x', `${diagonalShift.toFixed(2)}px`);
  };

  const queueWorksMotionUpdate = () => {
    if (wineScrollFrame) return;
    wineScrollFrame = requestAnimationFrame(() => {
      wineScrollFrame = 0;
      updateWorksWine();
      updateWorksModeTabs();
      updateWorksUxSmile();
      updateClassLessons();
    });
  };

  worksModeLinks.forEach((link) => {
    link.addEventListener('click', () => {
      setWorksMode(link.classList.contains('works-mode-tabs__tab--ux') ? 'ux' : 'ui');
    });
  });

  const setActiveUxType = (selectedButton) => {
    uxTypeButtons.forEach((button) => {
      const selected = button === selectedButton;
      button.classList.toggle('is-active', selected);
      button.setAttribute('aria-pressed', String(selected));
    });
  };

  const resetUxProject = () => {
    const previousActiveButton = activeUxType;
    activeUxType = null;
    uxDetailLoadToken += 1;
    setActiveUxType(null);
    worksUxPage?.classList.remove('is-project-active');
    uxProjectStage?.classList.remove('is-preview', 'is-detail', 'is-detail-ready');
    if (uxProjectDetail) {
      const detailHadFocus = document.activeElement === uxProjectDetail;
      uxProjectDetail.scrollTop = 0;
      uxProjectDetail.tabIndex = -1;
      if (detailHadFocus) previousActiveButton?.focus();
    }
  };

  const previewUxProject = (button) => {
    if (activeUxType || !uxProjectStage || !uxProjectPreview) return;
    const previewSource = button.dataset.preview;
    if (!previewSource) return;

    uxProjectPreview.src = previewSource;
    uxProjectPreview.alt = `UX 项目 ${button.dataset.uxType} 封面预览`;
    uxProjectStage.classList.remove('is-detail', 'is-detail-ready');
    uxProjectStage.classList.add('is-preview');
    if (uxProjectDetail) uxProjectDetail.tabIndex = -1;
    worksUxPage?.classList.add('is-project-active');
  };

  const clearUxProjectPreview = () => {
    if (activeUxType) return;
    worksUxPage?.classList.remove('is-project-active');
    uxProjectStage?.classList.remove('is-preview', 'is-detail', 'is-detail-ready');
  };

  const openUxProject = (button) => {
    if (!uxProjectStage || !uxProjectPreview || !uxProjectDetail || !uxProjectDetailImage) return;
    if (activeUxType === button) {
      resetUxProject();
      return;
    }

    activeUxType = button;
    setActiveUxType(button);
    worksUxPage?.classList.add('is-project-active');

    const projectNumber = button.dataset.uxType;
    const previewSource = button.dataset.preview;
    const detailSource = button.dataset.detail;
    if (previewSource) {
      uxProjectPreview.src = previewSource;
      uxProjectPreview.alt = `UX 项目 ${projectNumber} 封面预览`;
    }

    uxProjectStage.classList.remove('is-preview', 'is-detail-ready');
    uxProjectStage.classList.add('is-detail');
    uxProjectDetail.scrollTop = 0;
    uxProjectDetail.tabIndex = 0;
    uxProjectDetailImage.alt = `UX 项目 ${projectNumber} 完整项目页`;

    const loadToken = ++uxDetailLoadToken;
    const revealDetail = () => {
      if (loadToken !== uxDetailLoadToken || activeUxType !== button) return;
      uxProjectStage.classList.add('is-detail-ready');
      uxProjectDetail.scrollTop = 0;
    };

    uxProjectDetailImage.onload = revealDetail;
    uxProjectDetailImage.onerror = () => {
      if (loadToken === uxDetailLoadToken) uxProjectStage.classList.remove('is-detail-ready');
    };

    if (uxProjectDetailImage.dataset.source === detailSource && uxProjectDetailImage.complete && uxProjectDetailImage.naturalWidth) {
      requestAnimationFrame(revealDetail);
    } else {
      uxProjectDetailImage.dataset.source = detailSource || '';
      uxProjectDetailImage.src = detailSource || '';
    }
  };

  uxTypeButtons.forEach((button) => {
    button.addEventListener('pointerenter', () => previewUxProject(button));
    button.addEventListener('focus', () => previewUxProject(button));
    button.addEventListener('blur', clearUxProjectPreview);
    button.addEventListener('click', () => openUxProject(button));
    button.addEventListener('keydown', (event) => {
      const currentIndex = uxTypeButtons.indexOf(button);
      const nextIndex = event.key === 'ArrowDown' || event.key === 'ArrowRight'
        ? (currentIndex + 1) % uxTypeButtons.length
        : event.key === 'ArrowUp' || event.key === 'ArrowLeft'
          ? (currentIndex - 1 + uxTypeButtons.length) % uxTypeButtons.length
          : event.key === 'Home'
            ? 0
            : event.key === 'End'
              ? uxTypeButtons.length - 1
              : -1;
      if (nextIndex < 0) return;
      event.preventDefault();
      uxTypeButtons[nextIndex].focus();
    });

    const previewPreload = new Image();
    previewPreload.src = button.dataset.preview || '';
  });

  /* Treat the four UX tabs as one continuous hover corridor. Moving across
     their visual gaps must not briefly restore the smile between previews. */
  uxTypeSwitcher?.addEventListener('pointerleave', () => {
    if (!uxTypeSwitcher.contains(document.activeElement)) clearUxProjectPreview();
  });

  resetUxProject();

  classLessonButtons.forEach((button, index) => {
    const number = button.querySelector('span');
    if (number) number.textContent = `${index + 1}.`;
    button.addEventListener('pointerenter', () => selectClassLesson(index, { centerRail: false }));
    button.addEventListener('click', () => selectClassLesson(index, { syncScroll: true }));
    button.addEventListener('focus', () => selectClassLesson(index));
    button.addEventListener('keydown', (event) => {
      const delta = event.key === 'ArrowRight' || event.key === 'ArrowDown'
        ? 1
        : event.key === 'ArrowLeft' || event.key === 'ArrowUp'
          ? -1
          : 0;
      if (!delta) return;
      event.preventDefault();
      selectClassLesson(index + delta, { syncScroll: true, focus: true });
    });
  });

  classLessonRail?.addEventListener('scroll', syncClassLessonRailAngle, { passive: true });
  syncClassLessonRailAngle();

  if (classLessonButtons.length) selectClassLesson(0);

  classVariableTitles.forEach((title) => {
    if (title.dataset.proximityReady === 'true') return;
    title.dataset.proximityReady = 'true';

    const textGroups = [...title.querySelectorAll('[data-proximity-text]')];
    textGroups.forEach((group) => {
      const characters = [...group.textContent];
      group.textContent = '';
      characters.forEach((character) => {
        const letter = document.createElement('span');
        letter.dataset.proximityLetter = '';
        letter.textContent = character === ' ' ? '\u00a0' : character;
        group.append(letter);
      });
    });

    const letters = [...title.querySelectorAll('[data-proximity-letter]')];
    const resetLetters = () => {
      letters.forEach((letter) => {
        letter.style.setProperty('--letter-bold', '0px');
      });
    };

    title.addEventListener('pointermove', (event) => {
      if (reduceMotion.matches) return;
      letters.forEach((letter) => {
        const rect = letter.getBoundingClientRect();
        const distance = Math.hypot(event.clientX - (rect.left + rect.width / 2), event.clientY - (rect.top + rect.height / 2));
        const influence = clamp(1 - distance / 100, 0, 1);
        /* The site font is a static system face. Interpolating font-weight on
           every pointer frame makes Chromium briefly retain both rasterized
           glyphs on some DPRs, which reads as duplicated text. A bounded
           edge expansion gives the same emphasis without swapping glyphs. */
        letter.style.setProperty('--letter-bold', `${(1.15 * influence).toFixed(2)}px`);
      });
    });
    title.addEventListener('pointerleave', resetLetters);
    resetLetters();
  });

  const classWarpScrollSync = new Set();
  let classWarpScrollFrame = 0;
  let classWarpPointerX = -1;
  let classWarpPointerY = -1;

  document.addEventListener('pointermove', (event) => {
    classWarpPointerX = event.clientX;
    classWarpPointerY = event.clientY;
  }, { passive: true });

  window.addEventListener('scroll', () => {
    if (classWarpScrollFrame) return;
    classWarpScrollFrame = requestAnimationFrame(() => {
      classWarpScrollFrame = 0;
      classWarpScrollSync.forEach((syncHover) => syncHover(classWarpPointerX, classWarpPointerY));
    });
  }, { passive: true });

  const setupClassWarpTitle = (classWarpTitle) => {
    if (!classWarpTitle || reduceMotion.matches || classWarpTitle.dataset.warpReady === 'true') return;
    /* The portfolio title stays as a static heading. Its scroll entrance is
       preserved in CSS, but it should not react to pointer hover. */
    if (classWarpTitle.classList.contains('class-portfolio-title-warp')) return;
    classWarpTitle.dataset.warpReady = 'true';

    const canvas = document.createElement('canvas');
    canvas.className = 'class-warp-text__canvas';
    canvas.setAttribute('aria-hidden', 'true');
    classWarpTitle.append(canvas);

    const context = canvas.getContext('2d', { alpha: true });
    if (!context) return;

    const paddingXEm = .7;
    const canvasHeightEm = 1.7;
    const layers = new Map();
    const pointer = { x: .5, y: .5 };
    let logicalWidth = 1;
    let logicalHeight = 1;
    let titleWidth = 1;
    let fontSize = 16;
    let pixelRatio = 1;
    let progress = 0;
    let targetProgress = 0;
    let animationFrame = 0;
    let previousTime = performance.now();
    let rippleStart = -Infinity;
    let isVisible = true;
    const resetOnViewportExit = Boolean(classWarpTitle.closest('.class-panel--variable-ux'));

    const drawSourceLayer = (color) => {
      const layer = document.createElement('canvas');
      layer.width = canvas.width;
      layer.height = canvas.height;
      const layerContext = layer.getContext('2d');
      layerContext.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
      layerContext.clearRect(0, 0, logicalWidth, logicalHeight);
      layerContext.fillStyle = color;
      layerContext.textBaseline = 'alphabetic';

      const titleRect = classWarpTitle.getBoundingClientRect();
      const titleStyle = getComputedStyle(classWarpTitle);
      const baseline = (logicalHeight + fontSize * .73) / 2;

      const source = classWarpTitle.querySelector('.class-warp-text__source');
      const parts = source?.children.length ? [...source.children] : source ? [source] : [];
      parts.forEach((part) => {
        if (!(part instanceof HTMLSpanElement)) return;
        const partStyle = getComputedStyle(part);
        const partRect = part.getBoundingClientRect();
        layerContext.fillStyle = color || partStyle.color;
        layerContext.font = `${partStyle.fontWeight} ${fontSize}px ${titleStyle.fontFamily}`;
        if ('letterSpacing' in layerContext) layerContext.letterSpacing = titleStyle.letterSpacing;
        layerContext.fillText(part.textContent || '', paddingXEm * fontSize + partRect.left - titleRect.left, baseline);
      });
      return layer;
    };

    const rebuild = () => {
      const rect = classWarpTitle.getBoundingClientRect();
      const style = getComputedStyle(classWarpTitle);
      fontSize = parseFloat(style.fontSize) || 16;
      titleWidth = Math.max(1, rect.width);
      logicalWidth = Math.ceil(titleWidth + paddingXEm * fontSize * 2);
      logicalHeight = Math.ceil(fontSize * canvasHeightEm);
      pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.ceil(logicalWidth * pixelRatio);
      canvas.height = Math.ceil(logicalHeight * pixelRatio);
      context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
      layers.clear();
      /* Titles sharing the capability profile use the same green-dominant
         refraction material while retaining their own resting text colors. */
      const baseLayerColor = classWarpTitle.dataset.warpProfile === 'capability'
        ? '#28F54D'
        : undefined;
      layers.set('white', drawSourceLayer(baseLayerColor));
      layers.set('green', drawSourceLayer('#28F54D'));
      layers.set('pink', drawSourceLayer('#FF62E6'));
    };

    const render = (time) => {
      animationFrame = 0;
      const delta = Math.min(32, time - previousTime);
      previousTime = time;
      progress += (targetProgress - progress) * Math.min(1, delta * .012);
      if (Math.abs(targetProgress - progress) < .001) progress = targetProgress;
      classWarpTitle.style.setProperty('--warp-progress', progress.toFixed(4));

      context.clearRect(0, 0, logicalWidth, logicalHeight);
      const elapsed = time / 1000;
      const rippleAge = (time - rippleStart) / 1000;
      const sliceWidth = 2;
      const paddingX = paddingXEm * fontSize;
      const refraction = fontSize * .018 * progress;

      for (let x = 0; x < logicalWidth; x += sliceWidth) {
        const sourceX = Math.floor(x * pixelRatio);
        const sourceWidth = Math.ceil(Math.min(sliceWidth + .75, logicalWidth - x) * pixelRatio);
        const normalizedX = (x - paddingX) / Math.max(titleWidth, 1);
        const pointerDistance = normalizedX - pointer.x;
        const localInfluence = Math.exp(-(pointerDistance * pointerDistance) / .055) * .42;
        const idleWarp = Math.sin(normalizedX * Math.PI * 3.4 + elapsed * 3.45) * fontSize * .08;
        const pointerWarp = (pointer.y - .5) * fontSize * .38 * localInfluence;
        const ripple = rippleAge >= 0 && rippleAge < 1.4
          ? Math.sin(Math.abs(pointerDistance) * 27 - rippleAge * 12)
            * Math.exp(-Math.abs(pointerDistance) * 4.5)
            * Math.exp(-rippleAge * 2.2)
            * fontSize * .085
          : 0;
        const offsetY = (idleWarp + pointerWarp + ripple) * progress;

        context.drawImage(layers.get('green'), sourceX, 0, sourceWidth, canvas.height, x - refraction, offsetY, sourceWidth / pixelRatio, logicalHeight);
        context.drawImage(layers.get('pink'), sourceX, 0, sourceWidth, canvas.height, x + refraction, offsetY, sourceWidth / pixelRatio, logicalHeight);
        context.drawImage(layers.get('white'), sourceX, 0, sourceWidth, canvas.height, x, offsetY, sourceWidth / pixelRatio, logicalHeight);
      }

      if (isVisible && (targetProgress > 0 || progress > .002)) {
        animationFrame = requestAnimationFrame(render);
      } else if (progress <= .002) {
        progress = 0;
        classWarpTitle.style.setProperty('--warp-progress', '0');
      }
    };

    const startRendering = () => {
      if (animationFrame || !isVisible || document.hidden) return;
      previousTime = performance.now();
      animationFrame = requestAnimationFrame(render);
    };

    const resetWarpState = () => {
      targetProgress = 0;
      progress = 0;
      rippleStart = -Infinity;
      classWarpTitle.style.setProperty('--warp-progress', '0');
      context.clearRect(0, 0, logicalWidth, logicalHeight);
      if (animationFrame) cancelAnimationFrame(animationFrame);
      animationFrame = 0;
    };

    classWarpTitle.addEventListener('pointerenter', (event) => {
      const rect = classWarpTitle.getBoundingClientRect();
      pointer.x = clamp((event.clientX - rect.left) / Math.max(rect.width, 1), 0, 1);
      pointer.y = clamp((event.clientY - rect.top) / Math.max(rect.height, 1), 0, 1);
      /* A real pointer hit is a stronger visibility signal than the async
         IntersectionObserver callback. Titles inside the long sliced class
         page can become hoverable one frame before that callback catches up;
         previously that made the first hover appear completely inert. */
      if (resetOnViewportExit) resetWarpState();
      isVisible = true;
      rebuild();
      rippleStart = performance.now();
      targetProgress = 1;
      startRendering();
    });

    classWarpTitle.addEventListener('pointermove', (event) => {
      const rect = classWarpTitle.getBoundingClientRect();
      pointer.x = clamp((event.clientX - rect.left) / Math.max(rect.width, 1), 0, 1);
      pointer.y = clamp((event.clientY - rect.top) / Math.max(rect.height, 1), 0, 1);
      /* Keep the effect responsive if the pointer was already resting over
         the phrase while a pinned/translated slice moved underneath it. In
         that case browsers may not emit a fresh pointerenter after scrolling. */
      if (targetProgress === 0) {
        isVisible = true;
        rippleStart = performance.now();
        targetProgress = 1;
        startRendering();
      }
    });

    classWarpTitle.addEventListener('pointerdown', () => {
      rippleStart = performance.now();
      startRendering();
    });

    classWarpTitle.addEventListener('pointerleave', () => {
      if (resetOnViewportExit) {
        resetWarpState();
        return;
      }
      targetProgress = 0;
      startRendering();
    });

    classWarpScrollSync.add((clientX, clientY) => {
      if (clientX < 0 || clientY < 0) return;
      const rect = classWarpTitle.getBoundingClientRect();
      const pointerIsInside = clientX >= rect.left && clientX <= rect.right
        && clientY >= rect.top && clientY <= rect.bottom;
      if (!pointerIsInside || !isVisible) {
        if (resetOnViewportExit && (targetProgress > 0 || progress > 0)) {
          resetWarpState();
        }
        return;
      }
      pointer.x = clamp((clientX - rect.left) / Math.max(rect.width, 1), 0, 1);
      pointer.y = clamp((clientY - rect.top) / Math.max(rect.height, 1), 0, 1);
      isVisible = true;
      if (targetProgress === 0) rippleStart = performance.now();
      targetProgress = 1;
      startRendering();
    });

    const resizeObserver = new ResizeObserver(rebuild);
    resizeObserver.observe(classWarpTitle);
    const visibilityObserver = new IntersectionObserver(([entry]) => {
      isVisible = entry.isIntersecting || classWarpTitle.matches(':hover');
      if (!isVisible) {
        if (resetOnViewportExit) {
          /* Never preserve a half-crossfaded canvas while the UX panel is
             offscreen. Returning always starts from its single native text
             layer, so every later pointerenter can replay cleanly. */
          resetWarpState();
        } else if (animationFrame) {
          cancelAnimationFrame(animationFrame);
          animationFrame = 0;
        }
      } else if (isVisible && targetProgress > 0) {
        rebuild();
        startRendering();
      } else if (isVisible && classWarpPointerX >= 0 && classWarpPointerY >= 0) {
        const rect = classWarpTitle.getBoundingClientRect();
        const pointerIsInside = classWarpPointerX >= rect.left && classWarpPointerX <= rect.right
          && classWarpPointerY >= rect.top && classWarpPointerY <= rect.bottom;
        if (pointerIsInside) {
          pointer.x = clamp((classWarpPointerX - rect.left) / Math.max(rect.width, 1), 0, 1);
          pointer.y = clamp((classWarpPointerY - rect.top) / Math.max(rect.height, 1), 0, 1);
          rebuild();
          rippleStart = performance.now();
          targetProgress = 1;
          startRendering();
        }
      }
    });
    visibilityObserver.observe(classWarpTitle);
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && animationFrame) {
        cancelAnimationFrame(animationFrame);
        animationFrame = 0;
      } else if (!document.hidden && targetProgress > 0) {
        startRendering();
      }
    });
    rebuild();
  };

  classWarpTitles.forEach(setupClassWarpTitle);

  classFeedbackCards.forEach((card) => {
    const resetFeedbackTilt = () => {
      card.style.setProperty('--tilt-x', '0deg');
      card.style.setProperty('--tilt-y', '0deg');
      card.style.setProperty('--shine-x', '50%');
      card.style.setProperty('--shine-y', '50%');
    };

    card.addEventListener('pointermove', (event) => {
      if (reduceMotion.matches) return;
      const x = clamp(event.offsetX / Math.max(card.clientWidth, 1), 0, 1);
      const y = clamp(event.offsetY / Math.max(card.clientHeight, 1), 0, 1);
      card.style.setProperty('--tilt-x', `${((.5 - y) * 24).toFixed(2)}deg`);
      card.style.setProperty('--tilt-y', `${((x - .5) * 24).toFixed(2)}deg`);
      card.style.setProperty('--shine-x', `${(x * 100).toFixed(1)}%`);
      card.style.setProperty('--shine-y', `${(y * 100).toFixed(1)}%`);
    });

    card.addEventListener('pointerleave', resetFeedbackTilt);
  });

  if (classRingMore) {
    let activeRingMode = 0;
    const setRingImageState = (image, useHover) => {
      const nextSource = useHover ? image.dataset.hover : image.dataset.default;
      if (nextSource && image.getAttribute('src') !== nextSource) image.src = nextSource;
    };

    classRingImages.forEach((image) => {
      const card = image.closest('.class-ring-card');
      if (!card) return;
      card.addEventListener('pointerenter', () => setRingImageState(image, true));
      card.addEventListener('pointerleave', () => setRingImageState(image, activeRingMode === 1));

      const hoverImage = new Image();
      hoverImage.src = image.dataset.hover;
    });
    const target = { x: .5, y: .5, on: 0 };
    const current = { x: .5, y: .5, on: 0 };
    const lightSize = .4;
    const lightFade = .6;
    const aimBlend = .18;
    let glassFrame = 0;
    let glassStamp = 0;
    let glassBox = { width: 0, height: 0 };

    const measureGlassButton = () => {
      const rect = classRingMore.getBoundingClientRect();
      glassBox = { width: rect.width, height: rect.height };
      const radius = Math.max(rect.width, rect.height) * lightSize;
      classRingMore.style.setProperty('--glass-radius', `${radius.toFixed(1)}px`);
      classRingMore.style.setProperty('--glass-spill-radius', `${(radius * 1.9).toFixed(1)}px`);
    };

    const paintGlassButton = () => {
      const { width, height } = glassBox;
      classRingMore.style.setProperty('--glass-x', `${(current.x * 100).toFixed(2)}%`);
      classRingMore.style.setProperty('--glass-y', `${(current.y * 100).toFixed(2)}%`);
      classRingMore.style.setProperty('--glass-light-opacity', current.on.toFixed(3));

      const edgeDistance = clamp(Math.max(Math.abs(current.x - .5), Math.abs(current.y - .5)) * 2, 0, 1);
      let angle = 0;
      let halfArc = 30;

      if (width > 0 && height > 0) {
        const pointerX = current.x * width;
        const pointerY = current.y * height;
        const softness = Math.max(1, Math.min(width, height) * aimBlend);
        const sides = [
          [pointerX, 0, pointerY],
          [width - pointerX, width, pointerY],
          [pointerY, pointerX, 0],
          [height - pointerY, pointerX, height]
        ];
        const nearest = Math.min(...sides.map(([distance]) => distance));
        let weightTotal = 0;
        let aimX = 0;
        let aimY = 0;

        sides.forEach(([distance, sideX, sideY]) => {
          const weight = Math.exp(-(distance - nearest) / softness);
          weightTotal += weight;
          aimX += weight * sideX;
          aimY += weight * sideY;
        });

        const edgeX = aimX / weightTotal - width / 2;
        const edgeY = aimY / weightTotal - height / 2;
        angle = Math.atan2(edgeY, edgeX) * 180 / Math.PI + 90;
        const reach = Math.max(width, height) * lightSize * lightFade;
        halfArc = clamp(Math.atan(reach / Math.max(1, Math.hypot(edgeX, edgeY))) * 180 / Math.PI, 3, 70);
      }

      classRingMore.style.setProperty('--glass-start', `${(angle - halfArc).toFixed(1)}deg`);
      classRingMore.style.setProperty('--glass-peak', `${halfArc.toFixed(1)}deg`);
      classRingMore.style.setProperty('--glass-end', `${(halfArc * 2).toFixed(1)}deg`);
      classRingMore.style.setProperty('--glass-stroke-opacity', (current.on * edgeDistance * edgeDistance).toFixed(3));
    };

    const tickGlassButton = (timestamp) => {
      const delta = glassStamp ? Math.min(.05, (timestamp - glassStamp) / 1000) : 1 / 60;
      glassStamp = timestamp;
      const easing = 1 - Math.pow(1 - .201, delta * 60);
      current.x += (target.x - current.x) * easing;
      current.y += (target.y - current.y) * easing;
      current.on += (target.on - current.on) * easing;
      paintGlassButton();

      const settled = Math.abs(target.x - current.x) < .001
        && Math.abs(target.y - current.y) < .001
        && Math.abs(target.on - current.on) < .002;
      if (settled && target.on === 0) {
        current.x = target.x;
        current.y = target.y;
        current.on = 0;
        paintGlassButton();
        glassFrame = 0;
        glassStamp = 0;
        return;
      }
      glassFrame = requestAnimationFrame(tickGlassButton);
    };

    const startGlassButton = () => {
      if (reduceMotion.matches) {
        Object.assign(current, target);
        paintGlassButton();
      } else if (!glassFrame) {
        glassStamp = 0;
        glassFrame = requestAnimationFrame(tickGlassButton);
      }
    };

    const trackGlassPointer = (event) => {
      const rect = classRingMore.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      target.x = clamp((event.clientX - rect.left) / rect.width, 0, 1);
      target.y = clamp((event.clientY - rect.top) / rect.height, 0, 1);
      startGlassButton();
    };

    classRingMore.addEventListener('pointerenter', (event) => {
      const rect = classRingMore.getBoundingClientRect();
      if (rect.width && rect.height) {
        target.x = clamp((event.clientX - rect.left) / rect.width, 0, 1);
        target.y = clamp((event.clientY - rect.top) / rect.height, 0, 1);
        if (current.on === 0) {
          current.x = target.x;
          current.y = target.y;
        }
      }
      target.on = 1;
      startGlassButton();
    });
    classRingMore.addEventListener('pointermove', trackGlassPointer);
    classRingMore.addEventListener('pointerleave', (event) => {
      trackGlassPointer(event);
      target.on = 0;
      startGlassButton();
    });
    classRingMore.addEventListener('click', () => {
      activeRingMode = activeRingMode === 0 ? 1 : 0;
      classRingStage?.classList.toggle('is-hover-mode', activeRingMode === 1);
      classRingImages.forEach((image) => setRingImageState(image, activeRingMode === 1));
      classRingMore.setAttribute('aria-pressed', String(activeRingMode === 1));
    });

    measureGlassButton();
    paintGlassButton();
    if ('ResizeObserver' in window) new ResizeObserver(measureGlassButton).observe(classRingMore);
  }

  const createStickerPeelRenderer = (sticker) => {
    const canvas = sticker.querySelector('canvas');
    if (!canvas) return null;
    const gl = canvas.getContext('webgl', {
      alpha: true,
      antialias: true,
      premultipliedAlpha: true
    });
    if (!gl) return null;

    const compileShader = (type, source) => {
      const shader = gl.createShader(type);
      gl.shaderSource(shader, source);
      gl.compileShader(shader);
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
        gl.deleteShader(shader);
        return null;
      }
      return shader;
    };

    const vertexShader = compileShader(gl.VERTEX_SHADER, `
      precision highp float;
      attribute vec2 aPosition;
      attribute vec2 aUv;
      uniform float uCurl;
      varying vec2 vUv;
      varying float vLift;
      varying float vBackMix;

      void main() {
        const float PI = 3.141592653589793;
        const float CURL_FACTOR = 0.6;
        const float RADIUS = 0.1060660172;
        const float R_PRIME = 0.1767766953;
        const float MAX_DISTANCE = 0.6830127019;
        vec2 direction = vec2(-0.5, -0.8660254038);
        vec2 position = aPosition;
        float foldOffset = -MAX_DISTANCE + (1.0 - uCurl) * 2.0 * MAX_DISTANCE;
        float signedDistance = dot(position, direction) - foldOffset;
        float z = 0.0;
        float backMix = 0.0;

        if (signedDistance > 0.0) {
          float arcLimit = PI * RADIUS;
          float phi = PI * CURL_FACTOR;
          float xRelative;
          float angle;
          if (signedDistance <= arcLimit) {
            angle = signedDistance * CURL_FACTOR / RADIUS;
            xRelative = R_PRIME * sin(angle);
            z = R_PRIME * (1.0 - cos(angle));
          } else {
            float extra = signedDistance - arcLimit;
            angle = phi;
            xRelative = R_PRIME * sin(phi) + extra * cos(phi);
            z = R_PRIME * (1.0 - cos(phi)) + extra * sin(phi);
          }
          position += (xRelative - signedDistance) * direction;
          // The mesh bends in screen space, so its triangle winding does not
          // always flip when the flap visually turns over. Derive the visible
          // adhesive side from the physical curl angle instead.
          backMix = smoothstep(0.34, 0.92, angle);
        }

        float perspective = 1.0 / max(0.7, 1.0 - z * 0.82);
        // WebGL's negative clip-space Z is closer to the viewer. Keep the
        // screen-space curl, but lift its depth toward us so the edge folds up
        // instead of sinking into the artwork.
        gl_Position = vec4(position * 0.5 * perspective, -z * 0.22, 1.0);
        vUv = aUv;
        vLift = clamp(z * 4.2, 0.0, 1.0);
        vBackMix = backMix;
      }
    `);

    const fragmentShader = compileShader(gl.FRAGMENT_SHADER, `
      precision mediump float;
      uniform sampler2D uTexture;
      varying vec2 vUv;
      varying float vLift;
      varying float vBackMix;

      void main() {
        vec4 textureColor = texture2D(uTexture, gl_FrontFacing ? vUv : vec2(1.0 - vUv.x, vUv.y));
        if (textureColor.a < 0.015) discard;
        vec3 frontColor = textureColor.rgb * (0.94 + vLift * 0.48);
        // Cool silver adhesive: visibly darker and less chromatic than the
        // pearlescent face, with a restrained paper grain and fold highlight.
        float diagonalSheen = 0.5 + 0.5 * sin((vUv.x * 1.15 + vUv.y * 0.72) * 8.0);
        float backingLight = clamp(0.24 + vLift * 0.30 + diagonalSheen * 0.12, 0.0, 1.0);
        vec3 backColor = mix(vec3(0.50, 0.53, 0.57), vec3(0.82, 0.84, 0.87), backingLight);
        float grain = sin(vUv.x * 181.0) * sin(vUv.y * 167.0) * 0.014;
        backColor += vec3(grain);
        float backVisible = max(vBackMix, gl_FrontFacing ? 0.0 : 1.0);
        gl_FragColor = vec4(mix(frontColor, backColor, backVisible), textureColor.a);
      }
    `);

    if (!vertexShader || !fragmentShader) return null;
    const program = gl.createProgram();
    gl.attachShader(program, vertexShader);
    gl.attachShader(program, fragmentShader);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return null;
    gl.useProgram(program);

    const columns = 80;
    const rows = 60;
    const vertices = [];
    const indices = [];
    for (let row = 0; row <= rows; row += 1) {
      for (let column = 0; column <= columns; column += 1) {
        const x = column / columns;
        const y = row / rows;
        vertices.push(x - 0.5, y - 0.5, x, y);
      }
    }
    for (let row = 0; row < rows; row += 1) {
      for (let column = 0; column < columns; column += 1) {
        const a = row * (columns + 1) + column;
        const b = a + 1;
        const c = a + columns + 1;
        const d = c + 1;
        indices.push(a, b, d, a, d, c);
      }
    }

    const vertexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, vertexBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(vertices), gl.STATIC_DRAW);
    const stride = 4 * Float32Array.BYTES_PER_ELEMENT;
    const positionLocation = gl.getAttribLocation(program, 'aPosition');
    const uvLocation = gl.getAttribLocation(program, 'aUv');
    gl.enableVertexAttribArray(positionLocation);
    gl.vertexAttribPointer(positionLocation, 2, gl.FLOAT, false, stride, 0);
    gl.enableVertexAttribArray(uvLocation);
    gl.vertexAttribPointer(uvLocation, 2, gl.FLOAT, false, stride, 2 * Float32Array.BYTES_PER_ELEMENT);

    const indexBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indexBuffer);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, new Uint16Array(indices), gl.STATIC_DRAW);
    const curlLocation = gl.getUniformLocation(program, 'uCurl');
    const textureLocation = gl.getUniformLocation(program, 'uTexture');
    gl.uniform1i(textureLocation, 0);

    gl.clearColor(0, 0, 0, 0);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.enable(gl.DEPTH_TEST);
    gl.depthFunc(gl.LEQUAL);
    gl.disable(gl.CULL_FACE);

    let currentCurl = 0;
    let targetCurl = 0;
    let startCurl = 0;
    let startTime = 0;
    let animationFrame = 0;
    let textureReady = false;
    let resizeNeeded = true;

    const resize = () => {
      if (!resizeNeeded) return;
      const ratio = Math.min(window.devicePixelRatio || 1, 2);
      const width = Math.max(1, Math.round(canvas.clientWidth * ratio));
      const height = Math.max(1, Math.round(canvas.clientHeight * ratio));
      if (canvas.width !== width || canvas.height !== height) {
        canvas.width = width;
        canvas.height = height;
      }
      gl.viewport(0, 0, canvas.width, canvas.height);
      resizeNeeded = false;
    };

    const render = () => {
      if (!textureReady) return;
      resize();
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
      gl.uniform1f(curlLocation, currentCurl);
      gl.drawElements(gl.TRIANGLES, indices.length, gl.UNSIGNED_SHORT, 0);
    };

    const animateFrame = (time) => {
      const progress = clamp((time - startTime) / 360, 0, 1);
      const eased = progress * progress * (3 - 2 * progress);
      currentCurl = startCurl + (targetCurl - startCurl) * eased;
      render();
      if (progress < 1) animationFrame = requestAnimationFrame(animateFrame);
      else animationFrame = 0;
    };

    const setTarget = (nextCurl) => {
      targetCurl = clamp(nextCurl, 0, 1);
      cancelAnimationFrame(animationFrame);
      if (reduceMotion.matches) {
        currentCurl = targetCurl;
        render();
        return;
      }
      startCurl = currentCurl;
      startTime = performance.now();
      animationFrame = requestAnimationFrame(animateFrame);
    };

    const setImmediate = (nextCurl) => {
      cancelAnimationFrame(animationFrame);
      animationFrame = 0;
      targetCurl = clamp(nextCurl, 0, 1);
      currentCurl = targetCurl;
      render();
    };

    const source = new Image();
    source.decoding = 'async';
    source.addEventListener('load', () => {
      const textureCanvas = document.createElement('canvas');
      textureCanvas.width = 768;
      textureCanvas.height = 768;
      const context = textureCanvas.getContext('2d');
      context.clearRect(0, 0, 768, 768);
      context.save();
      context.beginPath();
      context.arc(384, 384, 380, 0, Math.PI * 2);
      context.clip();
      context.drawImage(source, 0, 0, 768, 768);
      context.restore();

      const texture = gl.createTexture();
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, texture);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, textureCanvas);
      textureReady = true;
      sticker.classList.add('is-peel-ready');
      render();
    }, { once: true });
    source.src = sticker === classStarSticker
      ? classStarStickerTexture
      : classSmileStickerTexture;

    const resizeObserver = new ResizeObserver(() => {
      resizeNeeded = true;
      render();
    });
    resizeObserver.observe(sticker);
    return { setTarget, setImmediate, render };
  };

  const setupDraggableSticker = (sticker) => {
    if (!sticker) return;
    const peelRenderer = createStickerPeelRenderer(sticker);
    let stickerPointerId = null;
    let stickerHovering = false;
    let stickerStartX = 0;
    let stickerStartY = 0;
    let stickerOriginX = 0;
    let stickerOriginY = 0;
    let stickerX = 0;
    let stickerY = 0;
    let stickerMoveFrame = 0;
    let pendingStickerX = 0;
    let pendingStickerY = 0;
    let stickerDragBounds = null;
    const hoverCurl = 0.58;

    const measureStickerBounds = () => {
      const stickerRect = sticker.getBoundingClientRect();
      const currentLeft = stickerRect.left - stickerX;
      const currentTop = stickerRect.top - stickerY;
      const inset = 8;
      const headerBottom = siteHeader?.getBoundingClientRect().bottom || 0;
      const safeTop = Math.max(0, headerBottom);
      return {
        minX: inset - currentLeft,
        maxX: window.innerWidth - inset - currentLeft - stickerRect.width,
        minY: safeTop + inset - currentTop,
        maxY: window.innerHeight - inset - currentTop - stickerRect.height
      };
    };

    const placeSticker = (nextX, nextY, bounds = measureStickerBounds()) => {
      if (!bounds) return;
      stickerX = clamp(nextX, bounds.minX, bounds.maxX);
      stickerY = clamp(nextY, bounds.minY, bounds.maxY);
      if (sticker === classStarSticker) {
        const isDisplaced = Math.abs(stickerX) > 0.5 || Math.abs(stickerY) > 0.5;
        sticker.classList.toggle('is-displaced', isDisplaced);
      }
      sticker.style.setProperty('--drag-x', `${stickerX.toFixed(2)}px`);
      sticker.style.setProperty('--drag-y', `${stickerY.toFixed(2)}px`);
    };

    const flushStickerMove = () => {
      if (!stickerMoveFrame) return;
      cancelAnimationFrame(stickerMoveFrame);
      stickerMoveFrame = 0;
      placeSticker(pendingStickerX, pendingStickerY, stickerDragBounds);
    };

    const finishStickerDrag = () => {
      flushStickerMove();
      if (stickerPointerId !== null && sticker.hasPointerCapture(stickerPointerId)) {
        sticker.releasePointerCapture(stickerPointerId);
      }
      stickerPointerId = null;
      stickerDragBounds = null;
      sticker.classList.remove('is-dragging');
      peelRenderer?.setTarget(stickerHovering ? hoverCurl : 0);
    };

    sticker.addEventListener('pointerenter', () => {
      stickerHovering = true;
      if (stickerPointerId === null) peelRenderer?.setTarget(hoverCurl);
    });

    sticker.addEventListener('pointerleave', () => {
      stickerHovering = false;
      if (stickerPointerId === null) peelRenderer?.setTarget(0);
    });

    sticker.addEventListener('pointerdown', (event) => {
      if (event.button !== 0) return;
      stickerPointerId = event.pointerId;
      stickerStartX = event.clientX;
      stickerStartY = event.clientY;
      stickerOriginX = stickerX;
      stickerOriginY = stickerY;
      stickerDragBounds = measureStickerBounds();
      pendingStickerX = stickerX;
      pendingStickerY = stickerY;
      event.preventDefault();
      sticker.setPointerCapture(event.pointerId);
      sticker.classList.add('is-dragging');
      peelRenderer?.setImmediate(0);
    });

    sticker.addEventListener('pointermove', (event) => {
      if (event.pointerId !== stickerPointerId) return;
      pendingStickerX = stickerOriginX + event.clientX - stickerStartX;
      pendingStickerY = stickerOriginY + event.clientY - stickerStartY;
      if (!stickerMoveFrame) {
        stickerMoveFrame = requestAnimationFrame(() => {
          stickerMoveFrame = 0;
          placeSticker(pendingStickerX, pendingStickerY, stickerDragBounds);
        });
      }
    });

    sticker.addEventListener('pointerup', finishStickerDrag);
    sticker.addEventListener('pointercancel', finishStickerDrag);

    sticker.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') {
        stickerX = 0;
        stickerY = 0;
        placeSticker(0, 0);
        return;
      }

      const step = event.shiftKey ? 24 : 8;
      const directions = {
        ArrowLeft: [-step, 0],
        ArrowRight: [step, 0],
        ArrowUp: [0, -step],
        ArrowDown: [0, step]
      };
      const direction = directions[event.key];
      if (!direction) return;
      event.preventDefault();
      placeSticker(stickerX + direction[0], stickerY + direction[1]);
    });
  };

  setupDraggableSticker(classSmileSticker);
  setupDraggableSticker(classStarSticker);

  if (classCanStage) {
    if (classCanStory && classCanLayerPanel && 'IntersectionObserver' in window) {
      const classCanLayerObserver = new IntersectionObserver(([entry]) => {
        classCanStory.classList.toggle('is-layer-active', entry.isIntersecting);
      }, { rootMargin: '10% 0px' });
      /* The first story slice can already touch the preceding ring viewport.
         Unlock overflow only when the second slice—the one whose live bottle
         intentionally crosses its seam—is itself close to the viewport. */
      classCanLayerObserver.observe(classCanLayerPanel);
    } else {
      classCanStory?.classList.add('is-layer-active');
    }

    const completeClassCanSequence = () => {
      classCanStage.classList.remove('is-playing');
      classCanStage.classList.add('is-complete');
    };

    const playClassCanSequenceOnce = () => {
      if (classCanStage.classList.contains('is-playing') || classCanStage.classList.contains('is-complete')) return;
      if (reduceMotion.matches) {
        completeClassCanSequence();
        return;
      }

      classCanStage.classList.add('is-playing');
      const copy = classCanStage.querySelector('.class-can-copy');
      copy?.addEventListener('animationend', completeClassCanSequence, { once: true });
      window.setTimeout(() => {
        if (!classCanStage.classList.contains('is-complete')) completeClassCanSequence();
      }, 5100);
    };

    const classCanPanel = classCanLayerPanel;
    let classCanTriggerFrame = 0;
    const stopClassCanTrigger = () => {
      window.removeEventListener('scroll', queueClassCanTrigger);
      window.removeEventListener('resize', queueClassCanTrigger);
    };
    const checkClassCanTrigger = () => {
      classCanTriggerFrame = 0;
      if (!classCanPanel || landing.dataset.page !== 'class') return;
      const headerBottom = document.querySelector('.site-header')?.getBoundingClientRect().bottom
        ?? window.innerHeight * 0.152;
      const panelRect = classCanPanel.getBoundingClientRect();
      if (panelRect.top > headerBottom + 1 || panelRect.bottom <= headerBottom) return;
      stopClassCanTrigger();
      playClassCanSequenceOnce();
    };
    function queueClassCanTrigger() {
      if (!classCanTriggerFrame) classCanTriggerFrame = requestAnimationFrame(checkClassCanTrigger);
    }
    window.addEventListener('scroll', queueClassCanTrigger, { passive: true });
    window.addEventListener('resize', queueClassCanTrigger, { passive: true });
    queueClassCanTrigger();
  }

  if (classPortfolioReveal) {
    const completePortfolioEntrance = () => classPortfolioReveal.classList.add('is-entered');
    classPortfolioReveal.classList.add('is-motion-ready');

    if (reduceMotion.matches) {
      completePortfolioEntrance();
    } else {
      let classPortfolioTriggerFrame = 0;
      const stopPortfolioTrigger = () => {
        window.removeEventListener('scroll', queuePortfolioTrigger);
        window.removeEventListener('resize', queuePortfolioTrigger);
      };
      const checkPortfolioTrigger = () => {
        classPortfolioTriggerFrame = 0;
        if (landing.dataset.page !== 'class') return;
        const revealRect = classPortfolioReveal.getBoundingClientRect();
        if (revealRect.top > window.innerHeight * 0.98 || revealRect.bottom <= 0) return;
        stopPortfolioTrigger();
        completePortfolioEntrance();
      };
      function queuePortfolioTrigger() {
        if (!classPortfolioTriggerFrame) {
          classPortfolioTriggerFrame = requestAnimationFrame(checkPortfolioTrigger);
        }
      }
      window.addEventListener('scroll', queuePortfolioTrigger, { passive: true });
      window.addEventListener('resize', queuePortfolioTrigger, { passive: true });
      queuePortfolioTrigger();
    }
  }

  if (classCapabilityPanel) {
    const revealCapabilityTitles = () => classCapabilityPanel.classList.add('is-capability-entered');
    classCapabilityPanel.classList.add('is-capability-motion-ready');

    if (reduceMotion.matches || !('IntersectionObserver' in window)) {
      revealCapabilityTitles();
    } else {
      const capabilityTitleObserver = new IntersectionObserver(([entry], observer) => {
        if (!entry.isIntersecting || landing.dataset.page !== 'class') return;
        revealCapabilityTitles();
        observer.disconnect();
      }, { rootMargin: '0px 0px -12% 0px', threshold: 0.15 });
      capabilityTitleObserver.observe(classCapabilityPanel);
    }
  }

  if (classCurriculumCopyMask) {
    const revealCurriculumCopy = () => classCurriculumCopyMask.classList.add('is-revealed');
    classCurriculumCopyMask.classList.add('is-motion-ready');

    if (reduceMotion.matches || !('IntersectionObserver' in window)) {
      revealCurriculumCopy();
    } else {
      const curriculumCopyObserver = new IntersectionObserver(([entry], observer) => {
        if (!entry.isIntersecting) return;
        revealCurriculumCopy();
        observer.disconnect();
      }, { rootMargin: '0px 0px -22% 0px', threshold: 0.08 });
      curriculumCopyObserver.observe(classCurriculumCopyMask);
    }
  }

  if (classValueListMasks.length) {
    const revealValueList = (mask) => mask.classList.add('is-revealed');
    classValueListMasks.forEach((mask) => mask.classList.add('is-motion-ready'));

    if (reduceMotion.matches || !('IntersectionObserver' in window)) {
      classValueListMasks.forEach(revealValueList);
    } else {
      const valueListObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          revealValueList(entry.target);
          observer.unobserve(entry.target);
        });
      }, { rootMargin: '0px 0px -22% 0px', threshold: 0.08 });
      classValueListMasks.forEach((mask) => valueListObserver.observe(mask));
    }
  }

  if (classPage && classPanels.length) {
    classPage.classList.add('is-reveal-ready');
    if ('IntersectionObserver' in window) {
      const classPanelObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add('is-visible');
          observer.unobserve(entry.target);
        });
      }, { rootMargin: '0px 0px -10% 0px', threshold: 0.08 });
      classPanels.forEach((panel) => {
        if (!panel.classList.contains('is-visible')) classPanelObserver.observe(panel);
      });
    } else {
      classPanels.forEach((panel) => panel.classList.add('is-visible'));
    }
  }

  let stageActivePhone = null;
  let stageRestingPhone = 3;
  let stageFlipTimer = 0;
  let stageSlideTimer = 0;
  let stagePointerId = null;
  let stagePointerCard = null;
  let stagePointerStartX = 0;
  let stagePointerDelta = 0;
  let stageSuppressClickUntil = 0;
  let stageWrapFrame = 0;

  const wrapPhoneIndex = (index) => {
    const total = uiPhoneCards.length;
    return total ? (index % total + total) % total : 0;
  };

  const getPhoneIndexDifference = (index, activeIndex) => {
    const total = uiPhoneCards.length;
    let difference = index - activeIndex;
    if (difference > total / 2) difference -= total;
    if (difference < -total / 2) difference += total;
    return difference;
  };

  const renderPhoneStage = (previousAnchor) => {
    uiPhoneTrack?.style.removeProperty('transform');
    window.cancelAnimationFrame(stageWrapFrame);
    uiPhoneCards.forEach((card) => card.classList.remove('is-wrapping'));
    const wrappingCards = [];
    const stageAnchor = stageActivePhone ?? stageRestingPhone;
    const priorAnchor = previousAnchor ?? stageAnchor;
    const hasActivePhone = stageActivePhone !== null;

    uiPhoneCards.forEach((card, index) => {
      const difference = getPhoneIndexDifference(index, stageAnchor);
      const previousDifference = getPhoneIndexDifference(index, priorAnchor);
      const distance = Math.abs(difference);
      const scale = hasActivePhone
        ? distance === 0 ? 1.85 : distance === 1 ? 1 : distance === 2 ? .94 : .88
        : 1;
      const opacity = hasActivePhone && distance === 3 ? .78 : 1;
      const crossesLoopBoundary = Math.abs(difference - previousDifference) > uiPhoneCards.length / 2;
      if (crossesLoopBoundary) {
        card.classList.add('is-wrapping');
        wrappingCards.push(card);
      }
      card.dataset.phoneIndex = String(index);
      card.classList.toggle('is-main', hasActivePhone && distance === 0);
      card.style.setProperty('--phone-x', `${difference * 17}cqw`);
      card.style.setProperty('--phone-y', hasActivePhone && distance === 0 ? '-5.61cqw' : '0cqw');
      card.style.setProperty('--phone-scale', String(scale));
      card.style.setProperty('--phone-opacity', String(opacity));
      card.style.setProperty('--phone-z', String(10 - distance));
    });

    if (wrappingCards.length) {
      uiPhoneGallery?.getBoundingClientRect();
      stageWrapFrame = requestAnimationFrame(() => {
        wrappingCards.forEach((card) => card.classList.remove('is-wrapping'));
      });
    }
  };

  const hydratePhoneSlides = (card) => {
    if (!card) return;
    card.querySelectorAll('.ui-phone-card__image--selected[data-src]').forEach((image) => {
      image.decoding = 'async';
      image.src = image.dataset.src;
      image.removeAttribute('data-src');
    });
  };

  const setPhoneSlide = (card, slideIndex) => {
    if (!card) return;
    const slides = [...card.querySelectorAll('.ui-phone-card__image--selected')];
    if (!slides.length) return;
    const normalizedIndex = (slideIndex % slides.length + slides.length) % slides.length;
    slides.forEach((slide, index) => slide.classList.toggle('is-current', index === normalizedIndex));
    card.dataset.phoneSlide = String(normalizedIndex);
  };

  const stopPhoneSlideshow = (resetSlides = true) => {
    window.clearInterval(stageSlideTimer);
    stageSlideTimer = 0;
    if (resetSlides) uiPhoneCards.forEach((card) => setPhoneSlide(card, 0));
  };

  const startPhoneSlideshow = (card) => {
    stopPhoneSlideshow(false);
    hydratePhoneSlides(card);
    setPhoneSlide(card, 0);
    if (reduceMotion.matches) return;

    stageSlideTimer = window.setInterval(() => {
      if (!card.classList.contains('is-flipped')) {
        stopPhoneSlideshow(false);
        return;
      }
      const currentIndex = Number(card.dataset.phoneSlide || 0);
      setPhoneSlide(card, currentIndex + 1);
    }, 1600);
  };

  const collapsePhoneStage = () => {
    window.clearTimeout(stageFlipTimer);
    stageFlipTimer = 0;
    stopPhoneSlideshow();
    uiPhoneCards.forEach((card) => {
      card.classList.remove('is-flipped');
      card.setAttribute('aria-pressed', 'false');
    });
  };

  const expandMainPhone = () => {
    if (stageActivePhone === null) return;
    const mainCard = uiPhoneCards[stageActivePhone];
    if (!mainCard) return;
    hydratePhoneSlides(mainCard);
    mainCard.classList.add('is-flipped');
    mainCard.setAttribute('aria-pressed', 'true');
    startPhoneSlideshow(mainCard);
  };

  const keepMainPhoneInView = () => {
    if (stageActivePhone === null) return;
    const mainCard = uiPhoneCards[stageActivePhone];
    if (!mainCard) return;

    const cardRect = mainCard.getBoundingClientRect();
    const headerBottom = document.querySelector('.site-header')?.getBoundingClientRect().bottom ?? 0;
    const safeTop = headerBottom + 12;
    const safeBottom = window.innerHeight - 20;
    let offset = 0;

    if (cardRect.top < safeTop) offset = cardRect.top - safeTop;
    else if (cardRect.bottom > safeBottom) offset = cardRect.bottom - safeBottom;

    if (Math.abs(offset) > 1) window.scrollBy({ top: Math.round(offset), behavior: 'auto' });
  };

  const resetPhoneStage = (resetPosition = false) => {
    const previousAnchor = stageActivePhone ?? stageRestingPhone;
    collapsePhoneStage();
    if (stageActivePhone !== null) stageRestingPhone = stageActivePhone;
    stageActivePhone = null;
    if (resetPosition) stageRestingPhone = Math.floor(uiPhoneCards.length / 2);
    renderPhoneStage(previousAnchor);
  };

  const activatePhoneCard = (card, expandAfterMove = true) => {
    if (!card) return;
    const nextIndex = Number(card.dataset.phoneIndex);
    const isCurrentMain = stageActivePhone !== null && nextIndex === stageActivePhone;

    if (isCurrentMain) {
      window.clearTimeout(stageFlipTimer);
      stageFlipTimer = 0;
      if (card.classList.contains('is-flipped')) resetPhoneStage();
      else {
        keepMainPhoneInView();
        expandMainPhone();
      }
      return;
    }

    collapsePhoneStage();
    /* Start decoding the selected work as soon as it is clicked, so the
       quicker flip never waits on an image at the end of the move. */
    hydratePhoneSlides(card);
    const previousAnchor = stageActivePhone ?? stageRestingPhone;
    stageActivePhone = wrapPhoneIndex(nextIndex);
    renderPhoneStage(previousAnchor);

    if (!expandAfterMove) return;
    const delay = reduceMotion.matches ? 0 : 210;
    stageFlipTimer = window.setTimeout(() => {
      stageFlipTimer = 0;
      keepMainPhoneInView();
      expandMainPhone();
    }, delay);
  };

  if (uiPhoneGallery && uiPhoneTrack && uiPhoneSequence) {
    renderPhoneStage();

    uiPhoneGallery.addEventListener('pointerdown', (event) => {
      if (event.button !== 0) return;
      stagePointerId = event.pointerId;
      stagePointerCard = event.target.closest('.ui-phone-card');
      stagePointerStartX = event.clientX;
      stagePointerDelta = 0;
      uiPhoneGallery.setPointerCapture(event.pointerId);
    });

    uiPhoneGallery.addEventListener('pointermove', (event) => {
      if (event.pointerId !== stagePointerId) return;
      stagePointerDelta = event.clientX - stagePointerStartX;
      if (Math.abs(stagePointerDelta) > 4) uiPhoneGallery.classList.add('is-dragging');
      uiPhoneGallery.style.setProperty('--phone-drag-x', `${stagePointerDelta}px`);
    });

    const endStagePointer = (event, cancelled = false) => {
      if (event.pointerId !== stagePointerId) return;
      const dragged = Math.abs(stagePointerDelta) > 4;
      if (dragged || stagePointerCard) stageSuppressClickUntil = performance.now() + 220;
      uiPhoneGallery.classList.remove('is-dragging');
      uiPhoneGallery.style.setProperty('--phone-drag-x', '0px');

      if (!cancelled && dragged) {
        const stepPixels = Math.max(window.innerWidth * .17, 1);
        const steps = Math.max(1, Math.round(Math.abs(stagePointerDelta) / stepPixels));
        const stageAnchor = stageActivePhone ?? stageRestingPhone;
        const nextIndex = wrapPhoneIndex(stageAnchor - Math.sign(stagePointerDelta) * steps);
        if (stageActivePhone === null) {
          const previousAnchor = stageRestingPhone;
          stageRestingPhone = nextIndex;
          renderPhoneStage(previousAnchor);
        } else {
          activatePhoneCard(uiPhoneCards[nextIndex], false);
        }
      } else if (!cancelled && stagePointerCard) {
        activatePhoneCard(stagePointerCard, true);
      }

      stagePointerId = null;
      stagePointerCard = null;
      stagePointerDelta = 0;
    };

    uiPhoneGallery.addEventListener('pointerup', endStagePointer);
    uiPhoneGallery.addEventListener('pointercancel', (event) => endStagePointer(event, true));
    uiPhoneGallery.addEventListener('click', (event) => {
      const card = event.target.closest('.ui-phone-card');
      if (!card || performance.now() < stageSuppressClickUntil) return;
      activatePhoneCard(card, true);
    });
  }

  document.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape') return;
    resetPhoneStage();
    resetUxProject();
  });

  const resolveRoute = () => {
    const route = location.hash.replace(/^#/, '').split(/[/?]/)[0];
    return ['works', 'works-gallery', 'works-ux', 'about', 'class'].includes(route) ? route : 'home';
  };

  const alignWorksSection = (route) => {
    const target = route === 'works' ? worksPage : document.getElementById(route);
    if (!target) return;

    const align = () => {
      const absoluteTop = window.scrollY + target.getBoundingClientRect().top;
      window.scrollTo({ top: Math.round(absoluteTop), behavior: 'auto' });
    };

    /* Native fragment scrolling can run after the first paint and place the
       section below the fixed header. Re-assert the exact section origin after
       layout and once more after decoded reference images settle. */
    requestAnimationFrame(() => requestAnimationFrame(align));
    window.setTimeout(align, 100);
    window.setTimeout(align, 260);
  };

  const renderRoute = () => {
    const route = resolveRoute();
    const page = route.startsWith('works') ? 'works' : route;
    const activeRoute = route.startsWith('works') ? 'works' : route;
    landing.dataset.page = page;
    landing.setAttribute(
      'aria-label',
      route.startsWith('works') ? 'Wine Joy Studio Works' : route === 'class' ? 'Wine Joy Studio Class' : 'Wine Joy Studio 首页'
    );

    siteHeader?.setActiveRoute(activeRoute);

    const inWorks = route.startsWith('works');
    worksFlow.setAttribute('aria-hidden', inWorks ? 'false' : 'true');
    worksPage.setAttribute('aria-hidden', inWorks ? 'false' : 'true');
    worksGalleryPage.setAttribute('aria-hidden', inWorks ? 'false' : 'true');
    worksUxPage.setAttribute('aria-hidden', inWorks ? 'false' : 'true');
    classPage.setAttribute('aria-hidden', route === 'class' ? 'false' : 'true');
    homePage.setAttribute('aria-hidden', route.startsWith('works') ? 'true' : 'false');

    if (inWorks) {
      resetClassCounters();
      alignWorksSection(route);
      if (route === 'works') replayWorksTileDrop();
      requestAnimationFrame(() => {
        updateWorksWine();
        updateWorksModeTabs();
        updateWorksUxSmile();
        renderPhoneStage();
      });
    } else {
      resetPhoneStage(true);
      resetUxProject();
      if (route === 'home' || route === 'class') {
        requestAnimationFrame(() => {
          window.scrollTo({ top: 0, behavior: 'auto' });
          if (route === 'class') {
            replayClassCounters();
            updateClassLessons();
          } else {
            resetClassCounters();
          }
        });
      }
    }
  };

  window.addEventListener('hashchange', renderRoute);
  window.addEventListener('scroll', queueWorksMotionUpdate, { passive: true });
  window.addEventListener('resize', queueWorksMotionUpdate, { passive: true });
  window.addEventListener('resize', () => renderPhoneStage(), { passive: true });
  reduceMotion.addEventListener?.('change', () => {
    queueWorksMotionUpdate();
    if (landing.dataset.page === 'class') replayClassCounters();
  });
  renderRoute();
})();
